function rotateWithCopy(matrix) {
  const n = matrix.length;
  const result = Array.from({ length: n }, () => new Array(n));
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) result[c][n - 1 - r] = matrix[r][c];
  }
  for (let r = 0; r < n; r++) matrix[r] = result[r];
}

function rotate(matrix) {
  const n = matrix.length;
  for (let r = 0; r < n; r++) {            // 1. transpose
    for (let c = r + 1; c < n; c++) {
      [matrix[r][c], matrix[c][r]] = [matrix[c][r], matrix[r][c]];
    }
  }
  for (const row of matrix) row.reverse(); // 2. reverse each row
}

class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;
        for (int r = 0; r < n; r++) {               // 1. transpose
            for (int c = r + 1; c < n; c++) {
                int temp = matrix[r][c];
                matrix[r][c] = matrix[c][r];
                matrix[c][r] = temp;
            }
        }
        for (int[] row : matrix) {                  // 2. reverse each row
            for (int left = 0, right = n - 1; left < right; left++, right--) {
                int temp = row[left];
                row[left] = row[right];
                row[right] = temp;
            }
        }
    }
}

class Solution {
public:
    void rotate(vector<vector<int>>& matrix) {
        int n = matrix.size();
        for (int r = 0; r < n; r++) {               // 1. transpose
            for (int c = r + 1; c < n; c++) {
                swap(matrix[r][c], matrix[c][r]);
            }
        }
        for (auto& row : matrix) {                  // 2. reverse each row
            reverse(row.begin(), row.end());
        }
    }
};
